/* Two shapes. A full-bleed split has no container, so the row is a direct child
   of the section and the copy carries the page gutter itself; a boxed card sits
   inside the container with a rule around it. */
[data-bz-section="media-band"] .bz-block { padding-block: 0 }
[data-bz-section="media-band"] .bz-block + .bz-block { padding-block-start: 22px }
[data-bz-section="media-band"] h2 { font-size: var(--text-h2); line-height: 1.15; margin: 0 }
[data-bz-section="media-band"] .bz-eyebrow { margin-bottom: 18px }
[data-bz-section="media-band"] [data-bz-node="mb-body"] p { font-size: 16px; line-height: 1.7; color: #3f3f3f }
[data-bz-section="media-band"] [data-bz-node="mb-body"] .bz-text { max-width: 46ch }
[data-bz-section="media-band"] .bz-btns { margin-block: 0 }
[data-bz-section="media-band"] [data-bz-node="mb-media"] { display: flex; min-height: 480px }
[data-bz-section="media-band"] [data-bz-node="mb-img"] { padding-block: 0; width: 100% }
[data-bz-section="media-band"] [data-bz-node="mb-img"] .bz-figure { margin: 0; height: 100% }
[data-bz-section="media-band"] [data-bz-node="mb-img"] img { width: 100%; height: 100%; object-fit: cover; display: block }

/* Full-bleed split: the copy half is padded to the page grid. */
[data-bz-section="media-band"] > .bz-section > [data-bz-node="mb-row"] > [data-bz-node="mb-copy"] {
  padding: 60px 40px 60px max(var(--container-pad), calc((100vw - var(--container)) / 2 + var(--container-pad)));
}
[data-bz-section="media-band"] > .bz-section > [data-bz-node="mb-row"] > [data-bz-node="mb-media"] { min-height: 480px }

/* Boxed card: a rule around the whole band, the copy padded inside it. */
[data-bz-section="media-band"] .bz-container > [data-bz-node="mb-row"] { border: 1px solid var(--line); background: var(--card) }
[data-bz-section="media-band"] .bz-container > [data-bz-node="mb-row"] > [data-bz-node="mb-copy"] { padding: 56px }
[data-bz-section="media-band"] .bz-container > [data-bz-node="mb-row"] > [data-bz-node="mb-media"] { min-height: 400px }
[data-bz-section="media-band"] .bz-section { padding-block: 0 }

@media (max-width: 1100px) {
  [data-bz-section="media-band"] > .bz-section > [data-bz-node="mb-row"] > [data-bz-node="mb-copy"] { padding: 48px var(--container-pad-tablet) }
  [data-bz-section="media-band"] [data-bz-node="mb-media"] { min-height: 320px }
}
@media (max-width: 640px) {
  [data-bz-section="media-band"] > .bz-section > [data-bz-node="mb-row"] > [data-bz-node="mb-copy"] { padding: 44px var(--container-pad-mobile) }
  [data-bz-section="media-band"] .bz-container > [data-bz-node="mb-row"] > [data-bz-node="mb-copy"] { padding: 32px 24px }
  [data-bz-section="media-band"] [data-bz-node="mb-media"] { min-height: 220px }
  [data-bz-section="media-band"] h2 { font-size: 28px }
}
/* The boxed variant carries the section rhythm on its container; the bleed
   variant is edge to edge with none. */
[data-bz-section="media-band"] > .bz-section > .bz-container { padding-block: var(--space-10) }
